function solve() {
  const fs = require('fs');
  const input = fs.readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/);
  const N = parseInt(input[0], 10);
  const K = parseInt(input[1], 10);
  const T = input.slice(2, 2 + N).map(Number);
  T.sort((a, b) => a - b);

  const INF = 1e15;
  const dp = new Array(N);
  const prev_pref = new Array(N);
  prev_pref.fill(0);

  const stack = [];

  for (let t = 1; t <= K; t++) {
    const limit = N - 3 * (K - t) - 2;
    dp.fill(INF);

    stack.length = 0;
    stack.push(N - 1); // optR
    stack.push(0);     // optL
    stack.push(limit); // r
    stack.push(0);     // l

    while (stack.length > 0) {
      const l = stack.pop();
      const r = stack.pop();
      const optL = stack.pop();
      const optR = stack.pop();
      if (l > r) continue;

      const mid = (l + r) >> 1;
      let best_i = -1;
      let best_val = INF;
      const start = optL;
      const end = Math.min(mid - 1, optR);
      const Tmid = T[mid];

      for (let i = start; i <= end; i++) {
        let prevCost;
        if (i === 0) {
          prevCost = (t === 1) ? 0 : INF;
        } else {
          prevCost = prev_pref[i - 1];
        }
        if (prevCost >= INF) continue;
        const diff = Tmid - T[i];
        const val = prevCost + diff * diff;
        if (val < best_val) {
          best_val = val;
          best_i = i;
        }
      }

      dp[mid] = best_val;
      if (best_i === -1) best_i = start;

      // push right child: (mid+1, r, best_i, optR)
      stack.push(optR);
      stack.push(best_i);
      stack.push(r);
      stack.push(mid + 1);

      // push left child: (l, mid-1, optL, best_i)
      stack.push(best_i);
      stack.push(optL);
      stack.push(mid - 1);
      stack.push(l);
    }

    if (t === K) {
      let ans = INF;
      for (let j = 0; j <= limit; j++) {
        if (dp[j] < ans) ans = dp[j];
      }
      console.log(ans);
      return;
    }

    let min_val = INF;
    for (let i = 0; i < N; i++) {
      if (dp[i] < min_val) min_val = dp[i];
      prev_pref[i] = min_val;
    }
  }
}

solve();
